mapper.select:
SELECT CONCAT(ab.id, '_', c.id) AS idKey,
       c.id                     AS clientId,
       c.client_name            AS clientName,
       ab.id                    AS checkPlanId,
       ab.plan_name             AS checkPlanName,
       ab.plan_type             AS planType,
       ab.check_way             AS checkWayCode,
       ac.belong_dept_id        AS bizDeptId,
       ac.belong_sponsor_id     AS projSponsorUserId,
       ab.dead_line             AS checkDate,
       ab.approval_status       AS reportProcessStatusCode,
       ab.plan_status           AS checkPlanStatus,
       ab.create_time           AS createTime,
       ab.update_time           AS updateTime
FROM new_after_lease_check_plan_client ac
         LEFT JOIN new_after_lease_check_plan_base ab ON ab.id = ac.plan_id
         LEFT JOIN client c ON c.id = ac.client_id
         LEFT JOIN new_after_lease_check_report_base cb ON ac.id = cb.check_plan_client_id
WHERE plan_status = 'CHECKING'
AND ac.approval_status IN ('UNDER_APPROVAL', 'UN_SUBMIT')

    AND cb.biz_dept_id in
    
        #{item}
    


    AND c.id = #{req.clientId}


    AND ac.belong_sponsor_id = #{req.projSponsorUserId}


    AND ac.approval_status = #{req.approvalStatus}


    ADD ab.plan_name LIKE CONCAT('%',#{req.checkPlanName}, '%')


    AND ab.plan_type = #{req.planType}


    AND ab.check_way = #{req.checkWayCode}


    AND ab.dead_line >= #{req.checkDateFrom}


    AND ab.dead_line <= #{req.checkDateTo}


    AND ab.plan_status = #{req.checkPlanStatus}


    AND ab.approval_status = #{req.reportProcessStatusCode}
